/**
 * One optional prop per recipe axis, the way a variant library derives props
 * from a consumer's own variant table. The alias is dependency-owned, but the
 * props it produces are keyed by the consumer's object and carry no
 * declaration of their own inside this package.
 */
export type Variants<Table> = {
  [Axis in keyof Table]?: keyof Table[Axis];
};
